import React, { useState } from 'react'
import "./society-widget.css"
import {  useDispatch, useSelector } from 'react-redux'
import {  getSoceityStatus, selectSocietyById } from '../../../../services/societies/reducers/societySlice'
import Button from '../../../../components/ui/Button'
import PostButton from '../../../../components/postButton/PostButton'
import PostModal from '../../../../components/ui/postModal/PostModal'
import { useParams } from 'react-router-dom'
import { getCurrentUser } from '../../../../libs/getCurrentUser'
import { exitSociety } from '../../../../services/societies/action/exitSociety'

const SocietyWidget = ({id}) => {
  const [showPostModal, setShowPostModal] = useState(false)
  const societyStatus = useSelector(getSoceityStatus)
  const currentSociety = useSelector(state => selectSocietyById(state, id))
  const dispatch = useDispatch()
  const currentUser = getCurrentUser()
  const {societyId} = useParams()

  const userInSociety = currentSociety?.societyMembers.find(society => society?.includes(currentUser.userUid))

  const handleExitSociety = async () => {
    if(!navigator.onLine || societyStatus === "loading"){
      return
    }
    try{
      const payload = {
        options: { method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${currentUser.userToken}
          `,
        },
        body: JSON.stringify({societyId, userId: currentUser.userUid})
      },
      societyId,
      userId: currentUser.userUid

      }
      dispatch(exitSociety(payload))
    }
    catch(error){
      console.log(error)
    }
  }
  
  return (
    <aside className="society-widget">
      {showPostModal && <PostModal setShowPostModal={setShowPostModal} id={societyId}  />}

      <div className="society-widget-wrapper">
      {<PostButton setShowPostModal={setShowPostModal} id={societyId} />}
        <div className="society-widget-img">
          <img src={currentSociety?.image_url} alt={`${currentSociety?.societyName}`} />
        </div>

        <div className="society-widget-text">
          <h3>{currentSociety?.societyName}</h3>
          <p>
           {currentSociety?.description}
          </p>
        </div>
      </div>
      
      <div className="society-widget-btn-container">
       {userInSociety && 
        <Button text={"Exit Society"} 
          className={"exit-society"} 
          handleEvent={() => handleExitSociety()}
        />}
      </div>
    </aside>
  )
}

export default SocietyWidget